<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/functions.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Request not found.');}$pdo=db();
$stmt=$pdo->prepare('SELECT cr.*,c.organization_name,c.description charity_description,c.contact_phone,u.name contact_name FROM clothing_requests cr JOIN charities c ON c.id=cr.charity_id JOIN users u ON u.id=c.user_id WHERE cr.id=? AND cr.status="active"');$stmt->execute([$id]);$request=$stmt->fetch();if(!$request){http_response_code(404);exit('This request is no longer available.');}$requirements=request_requirements($pdo,$id);$totals=request_totals($pdo,$id);$pct=$totals['needed']?min(100,round($totals['received']/$totals['needed']*100)):0;
$pageTitle=$request['title'];require __DIR__ . '/../includes/header.php'; ?>
<section class="detail-hero"><div class="shell detail-grid"><div><span class="eyebrow">A request from <?=e($request['organization_name'])?></span><h1><?=e($request['title'])?></h1><div class="request-meta"><span class="chip"><?=e($request['season'])?></span><span class="chip chip-sun"><?=e($request['urgency'])?> need</span><span class="chip">📍 <?=e($request['location'])?></span></div><p class="detail-description"><?=nl2br(e($request['description']))?></p></div><aside class="need-summary"><strong><?=$totals['remaining']?></strong><span>ITEMS STILL NEEDED</span><div class="progress"><span style="width:<?=$pct?>%"></span></div><small><?=$totals['received']?> received of <?=$totals['needed']?> needed</small></aside></div></section>
<section class="section" style="padding-top:20px"><div class="shell detail-grid"><div class="panel"><div class="panel-heading"><h2>What they’re looking for</h2><span class="chip chip-sun">Quality, clean & wearable</span></div><?php foreach($requirements as $r):?><article class="requirement-row"><div style="display:flex;justify-content:space-between;gap:14px"><div><h3><?=e($r['category'])?> <span class="muted">· <?=e($r['size_label'])?></span></h3><p><?=e($r['condition_note']?:'Clean, wearable items are welcome.')?></p></div><strong><?= (int)$r['quantity_remaining'] ?> left</strong></div></article><?php endforeach;?></div><aside class="panel"><h2>Ready to help?</h2><p class="section-description" style="margin:10px 0 20px">Pledge only what you have. <?=e($request['organization_name'])?> will review it, then you’ll pick a drop-off time.</p><?php $u=current_user(); if($u && $u['role']==='donor'):?><a class="button" href="<?=e(url('donor/pledge.php?request='.$id))?>">Pledge clothing →</a><?php elseif($u):?><p class="flash flash-info">Donor accounts can make pledges.</p><?php else:?><a class="button" href="<?=e(url('auth/login.php'))?>">Sign in to pledge →</a><p class="help">New here? <a class="text-link" href="<?=e(url('auth/register.php'))?>">Create a free donor account</a>.</p><?php endif;?><hr style="border:0;border-top:1px solid var(--line);margin:21px 0"><p class="help"><strong>Drop-off:</strong> <?=e($request['collection_location'])?><br><?=e($request['collection_notes']?:'Appointment details will be shared after approval.')?></p></aside></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
